#ifndef L4CSUM_H
#define L4CSUM_H

#include <stddef.h>

/*
 * Recompute the TCP/UDP checksum of an Ethernet frame (IPv4 or IPv6, optional
 * single 802.1Q tag). Used for frames the kernel handed to us with the
 * checksum still pending (TP_STATUS_CSUMNOTREADY): they were generated by the
 * local host and left for hardware offload, which never happens on our path.
 * Returns 1 if a checksum was rewritten, 0 if the frame was left untouched.
 */
int l4csum_fix(unsigned char *frame, size_t len);

#endif
